  submitBill(type,payload={},authorId=null){const author=this.city.society.citizen(authorId)||this.council.people()[0],executiveRequest=['worksBudget','worksTransfer'].includes(type)&&author?.id===this.city.economy.mayorId;if(!author||(!this.council.members.some(m=>m.citizenId===author.id)&&!executiveRequest))return this.city.fail('Selecione um vereador ou use o canal de solicitações do prefeito.');if(['tax','businessTax','salesTax','minimumWage','partyLimit','mayorCandidateLimit','reelectionLimit','termDays','campaignDays','pollMinRate','pollMaxRate','inflation','welfare','councilSeats','councilRate','councilBudget','mayorBudget','partyFund','worksBudget','worksTransfer'].includes(type)&&!Number.isFinite(payload.value))return this.city.fail('Valor de proposta inválido.');if(['nationalize','privatize'].includes(type)&&!this.city.building(payload.buildingId))return this.city.fail('Empresa indisponível.');if(type==='impeach'&&!this.scandals.some(s=>s.id===payload.caseId&&(s.accusedId===payload.targetId||s.participantIds?.includes(payload.targetId))&&scandalEligible(this,s)))return this.city.fail('Cassação exige provas, gravidade e grande repercussão popular.');this.city.lastError='';const proposal=this.council.propose(author,type,payload);return proposal===false?false:proposal||(this.city.lastError?null:this.city.fail('Já existe proposta semelhante em tramitação ou o tipo é inválido.'));}
