  canRun(c,office='mayor',nextTerm=false){if(!super.eligible(c))return false;if(this.policy.entrepreneurCandidates===false&&(c.businessIds?.length||this.city.development.projects.some(p=>(p.id===c.startupProjectId||p.accountId===c.accountId)&&!p.cancelled&&p.status!=='completed')))return false;const justice=this.city.justice;if(justice.cases.some(r=>(r.chargedCitizenId??r.offenderId)===c.id&&r.status==='convicted'&&(r.rule.politicalDisqualification||justice.policies.cleanRecord&&justice.policies.penalCode[r.type]?.cleanRecordDisqualifying)))return false;if(office==='mayor'&&nextTerm&&this.termNumber===0&&c.id===this.provisionalMayorId)return false;this.initializeCitizen(c);if(!this.party(c.political.partyId)?.active||this.party(c.political.partyId).retiring)return false;const record=c.political.tenure[office],term=this.termNumber+(nextTerm?1:0);if(c.political.blockedUntilTerm>term)return false;return !record||record.lastTerm<term-1||record.count<1+this.policy.reelectionLimit;}
