  join(c,party,reason='Afinidade ideológica'){this.initializeCitizen(c);if(!party?.active||!canJoin(this,c))return false;const old=this.party(c.political.partyId);if(old?.id===party.id){issuePartyCap(this,party,c);return true;}if(old){returnPartyCap(this,old,c);old.memberIds=old.memberIds.filter(id=>id!==c.id);c.political.lastPartyId=old.id;c.political.lastPartyDepartureAt=this.city.minute;}c.political.partyId=party.id;syncPartyColor(this,c);c.political.membershipSince=this.city.minute;c.political.loyalty=Math.max(.3,c.political.engagement*.7);if(!party.memberIds.includes(c.id))party.memberIds.push(c.id);issuePartyCap(this,party,c);for(const m of this.council.members)if(m.citizenId===c.id)m.partyId=party.id;this.council.ensureLeaderSuccession();this.remember(c,{kind:'party-membership',partyId:party.id,description:`Filiação a ${party.short}: ${reason}.`});this.standing.accepted(c,party);if(c.id===this.city.economy.mayorId||c.id===this.council.leaderId)this.syncGoverningFlag();return true;}
